```python
# tests/factories.py
import factory
from factory.django import DjangoModelFactory

from your_app.models import Order, User


class UserFactory(DjangoModelFactory):
    class Meta:
        model = User

    email = factory.Sequence(lambda n: f"user{n}@example.com")
    name = factory.Faker("name")


class OrderFactory(DjangoModelFactory):
    class Meta:
        model = Order

    user = factory.SubFactory(UserFactory)
    status = "draft"
```

```python
# tests/conftest.py
from unittest.mock import seal

import pytest

from tests.factories import OrderFactory, UserFactory
from your_app.payments import PaymentClient, PaymentResult


@pytest.fixture
def user(db):
    return UserFactory()


@pytest.fixture
def order(db, user):
    return OrderFactory(user=user)


@pytest.fixture
def payment_client_mock(mocker):
    client = mocker.create_autospec(PaymentClient, instance=True)
    client.charge.return_value = PaymentResult(
        success=True,
        transaction_id="tx_test_001",
    )
    seal(client)
    return client


@pytest.fixture
def patched_payment_client(mocker, payment_client_mock):
    return mocker.patch(
        "your_app.services.orders.PaymentClient",
        autospec=True,
        return_value=payment_client_mock,
    )
```

```python
# tests/test_example.py
def test_order_payment_uses_payment_client(order, patched_payment_client, payment_client_mock):
    # exercise your service here
    # result = pay_order(order.id)

    payment_client_mock.charge.assert_called_once()
```

